import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) =>
  ({ id, text, priority, required });
const frame = (s) => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cost = (s) => Buffer.byteLength(frame(s), 'utf8');

test('preserves special IDs, text, required ordering and optional ties', () => {
  const input = [
    section('__proto__', ' \r\n\0雪 ', 5),
    section('A', '', 0, true),
    section('a', '\ud800', Number.MAX_SAFE_INTEGER, true),
    section(' \n\0"雪', 'é', 5),
  ];
  input.forEach(Object.freeze);
  Object.freeze(input);
  const order = [input[1], input[2], input[0], input[3]];
  const text = order.map(frame).join('');
  assert.deepEqual(packContext(input, Buffer.byteLength(text)), {
    text, bytes: Buffer.byteLength(text), included: order.map((s) => s.id), omitted: [],
  });
});

test('skips oversized options and reports omissions in input order', () => {
  const input = [section('low', 'x'.repeat(100), 1), section('fit', '', 2),
    section('high', 'x'.repeat(100), 10), section('rule', '', 0, true)];
  const result = packContext(input, cost(input[1]) + cost(input[3]));
  assert.deepEqual(result.included, ['rule', 'fit']);
  assert.deepEqual(result.omitted, ['low', 'high']);
  assert.equal(result.bytes, Buffer.byteLength(result.text));
  assert.throws(() => packContext([input[3]], cost(input[3]) - 1), Error);
});

test('rejects malformed budgets and all malformed sections even with zero budget', () => {
  for (const budget of [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1,
    '0', null, undefined, true, 0n]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const input of [null, {}, 'x', new Array(1), [null], [[]], [1]]) {
    assert.throws(() => packContext(input, 0), Error);
  }
  for (const [field, values] of Object.entries({
    id: ['', 1, null, undefined], text: [1, null, undefined],
    priority: [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '1', undefined],
    required: [0, 1, 'false', null, undefined],
  })) {
    for (const value of values) {
      assert.throws(() => packContext([section('valid'),
        { ...section('invalid'), [field]: value }], 0), Error);
    }
  }
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER),
    { text: '', bytes: 0, included: [], omitted: [] });
});

test('CLI success, errors and side-effect-free import', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
