+  const result = packContext(input, cost(input[1]) + cost(input[3]));
+  assert.deepEqual(result.included, ['rule', 'fit']);
+  assert.deepEqual(result.omitted, ['low', 'high']);
+  assert.equal(result.bytes, Buffer.byteLength(result.text));
+  assert.throws(() => packContext([input[3]], cost(input[3]) - 1), Error);
+});
+
+test('rejects malformed budgets and all malformed sections even with zero budget', () => {
+  for (const budget of [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1,
+    '0', null, undefined, true, 0n]) {
+    assert.throws(() => packContext([], budget), Error);
+  }
+  for (const input of [null, {}, 'x', new Array(1), [null], [[]], [1]]) {
+    assert.throws(() => packContext(input, 0), Error);
+  }
+  for (const [field, values] of Object.entries({
+    id: ['', 1, null, undefined], text: [1, null, undefined],
+    priority: [-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '1', undefined],
+    required: [0, 1, 'false', null, undefined],
+  })) {
+    for (const value of values) {
+      assert.throws(() => packContext([section('valid'),
+        { ...section('invalid'), [field]: value }], 0), Error);
+    }
+  }
+  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
+  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER),
+    { text: '', bytes: 0, included: [], omitted: [] });
+});
+
+test('CLI success, errors and side-effect-free import', () => {
+  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  const script = fileURLToPath(new URL('../context-packet.js', import.meta.url));
+  const run = (args) => spawnSync(process.execPath, args, { encoding: 'utf8' });
+  const failure = (args) => {
+    const result = run([script, ...args]);
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, '');
+    assert.ok(result.stderr.length > 0);
+  };
+  try {
+    const path = join(directory, 'input.json');
+    const input = { sections: [section('雪', ' é\r\n ')], maxBytes: 100, extra: true };
+    writeFileSync(path, JSON.stringify(input));
+    const result = run([script, path]);
+    assert.equal(result.status, 0);
+    assert.equal(result.stderr, '');
+    assert.equal(result.stdout, JSON.stringify(packContext(input.sections, 100)) + '\n');
+    failure([]);
+    failure([path, path]);
+    failure([join(directory, 'missing.json')]);
+    for (const content of ['{', 'null', '[]', '{}',
+      JSON.stringify({ sections: [section('required', '', 0, true)], maxBytes: 0 }),
+      JSON.stringify({ sections: [section('invalid', '', -1)], maxBytes: 0 })]) {
+      writeFileSync(path, content);
+      failure([path]);
+    }
+    const imported = run(['--input-type=module', '-e',
+      `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)};`]);
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});

